import Foundation
import CoreML
import Vision
import ImageIO

let root = URL(fileURLWithPath: CommandLine.arguments[1])
let config = MLModelConfiguration()
config.computeUnits = .cpuOnly
let model = try VNCoreMLModel(for: MLModel(contentsOf: root.appendingPathComponent("compiled/yolo26s_face_plate_sign.mlmodelc"), configuration: config))
var rows: [[String: Any]] = []
for name in ["tsr-panoramax-0906fc23", "tsr-panoramax-49e25e66"] {
    let request = VNCoreMLRequest(model: model)
    request.imageCropAndScaleOption = .scaleFit
    try VNImageRequestHandler(url: root.appendingPathComponent(name + "-window.png")).perform([request])
    let objects = request.results as? [VNRecognizedObjectObservation] ?? []
    let signs = objects.filter { $0.labels.first?.identifier == "sign" }
    guard !signs.isEmpty else { fatalError("No Vision sign object for " + name) }
    rows.append(["fixture": name, "recognized_objects": objects.count, "sign_objects": signs.count,
                 "top_sign_score": signs.map { Double($0.confidence) }.max()!,
                 "labels": objects.compactMap { $0.labels.first?.identifier }])
}
let data = try JSONSerialization.data(withJSONObject: ["platform": "macOS Vision CPU_ONLY", "rows": rows], options: [.prettyPrinted, .sortedKeys])
try data.write(to: root.appendingPathComponent("vision-probe.json"))
print(String(data: data, encoding: .utf8)!)
